#!/bin/bash
#
# clean_files.sh
#
# Deletes compilation output and temporary files from every Java/Maven, Dart,
# Flutter and NodeJS project in this repository. Everything removed here is
# regenerated by building or running the projects again (mvn package,
# flutter pub get, flutter run, npm install, ...).
#
# Usage:
#   ./clean_files.sh             delete the files
#   ./clean_files.sh --dry-run   only list what would be deleted
#
# Safety: anything that contains files tracked by git is never deleted.

set -u

DRY_RUN=0

for arg in "$@"; do
    case "$arg" in
        -n|--dry-run)   DRY_RUN=1 ;;
        -h|--help)      sed -n '3,14p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
        *)              echo "Unknown option: $arg (try --help)" >&2; exit 2 ;;
    esac
done

# Always work from the repository root, wherever the script is called from
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$ROOT" || exit 1

IN_GIT=0
if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
    IN_GIT=1
fi

TOTAL_KB=0
COUNT=0
SKIPPED=0
LISTED_DIRS=()

# True when the path is, or contains, a file tracked by git
is_tracked() {
    [ "$IN_GIT" -eq 1 ] || return 1
    [ -n "$(git --literal-pathspecs ls-files -- "$1" 2>/dev/null | head -n 1)" ]
}

# Delete one file or folder (or just report it with --dry-run)
remove() {
    local path="$1" kb
    [ -e "$path" ] || [ -L "$path" ] || return 0

    if is_tracked "$path"; then
        echo "  skipped (tracked by git): $path"
        SKIPPED=$((SKIPPED + 1))
        return 0
    fi

    kb=$(du -sk "$path" 2>/dev/null | cut -f1)
    kb=${kb:-0}

    if [ "$DRY_RUN" -eq 1 ]; then
        # Do not list (or count) again what is inside an already listed folder
        local dir
        for dir in ${LISTED_DIRS[@]+"${LISTED_DIRS[@]}"}; do
            case "$path" in "$dir"/*) return 0 ;; esac
        done
        [ -d "$path" ] && LISTED_DIRS+=("$path")
        printf '  would delete %8s KB  %s\n' "$kb" "$path"
    else
        if ! rm -rf "$path"; then
            echo "  could not delete: $path" >&2
            return 0
        fi
        printf '  deleted %8s KB  %s\n' "$kb" "$path"
    fi
    TOTAL_KB=$((TOTAL_KB + kb))
    COUNT=$((COUNT + 1))
}

# Run find from the root (never entering .git or node_modules) and remove every
# result. Arguments are a find expression.
clean() {
    local path
    while IFS= read -r -d '' path; do
        remove "$path"
    done < <(find . \( -type d \( -name .git -o -name node_modules \) -prune \) -o \
                    \( "$@" \) -print0 2>/dev/null)
}

# Like clean, but only for folders that have the given project file beside them
# (for example "target" only counts next to a pom.xml).
clean_dir_beside() {
    local name="$1" path parent marker found
    shift
    while IFS= read -r -d '' path; do
        parent="$(dirname "$path")"
        found=0
        for marker in "$@"; do
            [ -e "$parent/$marker" ] && found=1
        done
        [ "$found" -eq 1 ] && remove "$path"
    done < <(find . \( -type d \( -name .git -o -name node_modules \) -prune \) -o \
                    \( -type d -name "$name" -prune -print0 \) 2>/dev/null)
}

if [ "$DRY_RUN" -eq 1 ]; then
    echo "Dry run: nothing will be deleted"
fi

echo "Java / Maven"
clean_dir_beside target pom.xml
clean -type f \( -name '*.class' -o -name 'dependency-reduced-pom.xml' \
              -o -name 'hs_err_pid*.log' -o -name 'replay_pid*.log' \)

echo "Dart / Flutter"
clean -type d -name .dart_tool -prune
clean_dir_beside build    pubspec.yaml build.gradle build.gradle.kts
clean_dir_beside coverage pubspec.yaml
clean -type d -path '*/doc/api' -prune
clean -type f \( -name .flutter-plugins -o -name .flutter-plugins-dependencies \)

echo "Flutter platform folders (android, ios, macos, linux, windows)"
clean -type d \( -path '*/android/.gradle' -o -path '*/android/.kotlin' \
              -o -path '*/android/app/.cxx' \
              -o -path '*/Flutter/ephemeral' -o -path '*/flutter/ephemeral' \
              -o -path '*/ios/Pods' -o -path '*/macos/Pods' \
              -o -path '*/ios/.symlinks' -o -path '*/macos/.symlinks' \
              -o -path '*/ios/Flutter/App.framework' \
              -o -path '*/ios/Flutter/Flutter.framework' \
              -o -name xcuserdata -o -name DerivedData \) -prune
clean -type f \( -path '*/android/local.properties' \
              -o -path '*/ios/Flutter/Generated.xcconfig' \
              -o -path '*/ios/Flutter/flutter_export_environment.sh' \
              -o -path '*/ios/Flutter/Flutter.podspec' \
              -o -path '*/ios/Flutter/.last_build_id' \
              -o -name 'GeneratedPluginRegistrant.java' \
              -o -name 'GeneratedPluginRegistrant.h' \
              -o -name 'GeneratedPluginRegistrant.m' \
              -o -name 'GeneratedPluginRegistrant.swift' \
              -o -name 'generated_plugin_registrant.cc' \
              -o -name 'generated_plugin_registrant.h' \)

echo "Temporary files"
clean -type d -name __pycache__ -prune
clean -type f \( -name .DS_Store -o -name '._*' -o -name '*~' -o -name '*.swp' \
              -o -name '*.tmp' -o -name 'dades.sqlite' \)

echo "NodeJS"
while IFS= read -r -d '' path; do
    remove "$path"
done < <(find . \( -type d -name .git -prune \) -o \
                \( -type d -name node_modules -prune -print0 \) 2>/dev/null)

echo
if [ "$DRY_RUN" -eq 1 ]; then
    echo "Would delete $COUNT items, $((TOTAL_KB / 1024)) MB"
else
    echo "Deleted $COUNT items, $((TOTAL_KB / 1024)) MB freed"
fi
if [ "$SKIPPED" -gt 0 ]; then
    echo "Skipped $SKIPPED items tracked by git"
fi
